import type { Client } from "pg";

export function requireLocalResetUrl(env: Record<string, string | undefined>) {
  if (env.NODE_ENV === "production") throw new Error("Local resets only.");
  const url = new URL(env.DATABASE_URL ?? "");
  // Prisma's usual public-schema parameter does not change the destination.
  if (url.searchParams.get("schema") === "public")
    url.searchParams.delete("schema");
  if (
    !["postgres:", "postgresql:"].includes(url.protocol) ||
    !["localhost", "127.0.0.1"].includes(url.hostname) ||
    url.port !== "5433" ||
    decodeURIComponent(url.pathname.slice(1)) !==
      (env.POSTGRES_DB || "mailloop") ||
    url.search ||
    url.hash
  )
    throw new Error(
      "Expected the local Docker database on port 5433 without URL parameters.",
    );
  return url.toString();
}

const quote = (name: string) => '"' + name.replaceAll('"', '""') + '"';

// Caller owns a dedicated connection. Dry runs execute the same work, then roll back.
export async function resetLocalData(client: Client, apply: boolean) {
  await client.query("BEGIN");
  try {
    await client.query("SET LOCAL lock_timeout = '5s'");
    const { rows: schemaRows } = await client.query<{ schema: string }>(
      "SELECT current_schema() AS schema",
    );
    const schema = quote(schemaRows[0].schema);
    const controlTable = `${schema}."SystemControl"`;
    const { rows: before } = await client.query(
      `SELECT * FROM ${controlTable} WHERE key='global' FOR UPDATE`,
    );
    if (before.length !== 1) {
      throw new Error(
        "Required global system settings are missing. Restore them before resetting data.",
      );
    }
    const { rows: tables } = await client.query<{ tablename: string }>(
      "SELECT tablename FROM pg_tables WHERE schemaname=current_schema() AND tablename NOT IN ('SystemControl', '_prisma_migrations') ORDER BY tablename",
    );
    if (!tables.length) throw new Error("No application tables found.");
    const auditTable = `${schema}."AdminAuditLog"`;
    await client.query(
      `ALTER TABLE ${auditTable} DISABLE TRIGGER admin_audit_truncate`,
    );
    // Explicit table list: never cascade into system configuration or migrations.
    await client.query(
      `TRUNCATE TABLE ${tables.map(({ tablename }) => `${schema}.${quote(tablename)}`).join(", ")} RESTART IDENTITY`,
    );
    await client.query(
      `ALTER TABLE ${auditTable} ENABLE TRIGGER admin_audit_truncate`,
    );
    for (const { tablename } of tables) {
      const { rows } = await client.query(
        `SELECT count(*)::int AS count FROM ${schema}.${quote(tablename)}`,
      );
      if (rows[0].count !== 0)
        throw new Error("Application data was not cleared.");
    }
    const { rows: after } = await client.query(
      `SELECT * FROM ${controlTable} WHERE key='global'`,
    );
    if (JSON.stringify(before) !== JSON.stringify(after))
      throw new Error("System settings changed; rolling back.");
    await client.query(apply ? "COMMIT" : "ROLLBACK");
    return {
      applied: apply,
      clearedTables: tables.length,
      systemSettingsPreserved: true,
    };
  } catch (error) {
    await client.query("ROLLBACK");
    throw error;
  }
}
